            ) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Icon(Icons.Default.Recommend, contentDescription = null, tint = DemonicGoldBright, modifier = Modifier.size(18.dp))
                        Spacer(modifier = Modifier.width(6.dp))
                        Text(
                            text = "Proponowany ekwipunek dla: ${hero.heroClass.displayName}",
                            color = DemonicGoldBright,
                            fontSize = 15.sp,
                            fontWeight = FontWeight.Bold
                        )
                    }

                    FilledTonalButton(
                        onClick = { viewModel.equipRecommendedLoadout() },
                        colors = ButtonDefaults.filledTonalButtonColors(
                            containerColor = DemonicGoldDark,
                            contentColor = DemonicGoldBright
                        ),
                        contentPadding = PaddingValues(horizontal = 8.dp, vertical = 2.dp),
                        modifier = Modifier.defaultMinSize(minHeight = 28.dp)
